"use client";

// Shared data store: demo data (generated by the real CIE engine) or the
// user's own exported files. Zustand keeps it simple — no backend needed.
//
// The workspace layout (inspired by a code-intelligence UI) has three zones:
//   topbar  — model picker + repo chip + main menus
//   stage   — the chart engine in the middle (map, charts, story pages)
//   chat    — Ask CIE on the right, wired to the stage
// so the store also carries which view the stage shows, any chart the chat
// asked it to render big, and the map bubble the user picked (which the chat
// offers as a referent).

import { addChipState, addContext, type ChatContextElement } from "./chat-context";
import { create } from "zustand";
import type { CieReport, CieViewSpec, ConceptTree, VizElement, CieDeps, CieRuntime, CieStories, CieQuality, CieCochange, CieOverlap, CieDrift } from "./cie-types";
import type { TechStack } from "./stack-types";
import type { PolyglotBundle } from "./polyglot-types";
import type { ChatChartSpec, MasteryCardData } from "./chat-chart";
import type { RepoScan } from "./language-profiles";
import { DEFAULT_LLM, loadLlmConfig, saveLlmConfig, type LlmConfig } from "./llm-config";
import { rememberWorkspace } from "./workspace-memory";
import { freshMastery, loadMasteryState, masteryKeyOf, saveMasteryState, type MasteryState } from "./mastery";
import { ATLAS_RESET, scopeForRef, containerOfPath, type AtlasRef, type AtlasSelection } from "./atlas";
import { nextChartFilter, type ChartFilter } from "./chart-filter";
import { PERSONA_PRESETS, loadPersonaMemory, savePersonaMemory, type PersonaId } from "./atlas-presets";

export type DataSource = "demo" | "custom" | null;

const CHAT_OPEN_KEY = "cie.chatOpen.v1";

// Every page the middle stage can show. "chart" renders a chart the chat
// (or a menu tap) sent to the canvas. "mastery" is the guided 5-station
// journey. "atlas" is the multi-view dashboard — four synchronized views
// over one Selection Context (lib/atlas.ts).
export type StageView =
  | "start"
  | "map"
  | "mindmap"
  | "does"
  | "usecases"
  | "fixes"
  | "promises"
  | "numbers"
  | "menu"
  | "trust"
  | "deps"
  | "runtime"
  | "quality"
  | "mastery"
  | "atlas"
  | "polyglot"
  | "admin"
  | "chart";

/** A concept diagram on the canvas: which usecase, drawn which way. The
 *  ViewSpec itself is never stored — it is derived on render from
 *  (concept, report) by the B3 mappers, so the canvas always shows what
 *  the loaded artifacts can actually evidence. */
export interface CanvasConcept {
  conceptId: number;
  kind: "flowchart" | "sequence";
}

// One bubble in the "Ask CIE" conversation. `chart` is the complementary
// chart the AI attached to its answer (US-020 catalog pick), if any. Failed
// sends carry `technical` (collapsible) and `providerIssue` (offer to open
// the connection settings). `instant` marks answers drawn locally from the
// loaded store (draw-anything.ts) — no AI was involved, and the footer says
// so instead of naming a provider.
//        (or a menu tap) sent to the canvas.
export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  error?: boolean;
  chart?: ChatChartSpec;
  card?: MasteryCardData; // mastery journey cards — entry points, flows, trace (with the verify loop), 5 things
  technical?: string;
  providerIssue?: boolean;
  instant?: boolean;
}

/**
 * "Show me the code" — a chart element with a known source location opened
 * the source panel. Carries everything the panel needs: where to look, which
 * byte offsets/line to highlight, and which chart element asked (so the
 * panel's "Ask CIE about this" button can hand a grounded question to chat).
 */
export interface SourceViewerRequest {
  file: string; // repo-relative path, exactly as the exports name it
  line?: number; // flat real line number when the export carried one
  endLine?: number;
  byteStart?: number; // report.json symbols[].loc — resolved to a line
  byteEnd?: number; // only when the file's content is available
  elName?: string;
  elValue?: number | string;
  chartTitle?: string;
}

interface CieState {
  report: CieReport | null;
  viewspec: CieViewSpec | null;
  concepts: ConceptTree | null;
  deps: CieDeps | null; // dependency manifests (cie deps export) — null when none
  runtime: CieRuntime | null; // collected runtime evidence — null when the project has none
  stories: CieStories | null; // the 33 story demos with real data — null when the project has none
  quality: CieQuality | null; // health/quality ETL export — null when the project has none
  cochange: CieCochange | null; // git co-change coupling (cie cochange) — null when none, or too shallow a clone to mine
  overlap: CieOverlap | null; // capability overlap over the concept tree (cie overlap) — null when none
  drift: CieDrift | null; // real claim-extraction + verification over the project's own docs (cie drift) — null when no docs found
  stack: TechStack | null; // the engine's tech-stack artifact (cie stack) — null when the pass found nothing
  polyglotSpecs: PolyglotBundle | null; // PRD v2.0 polyglot bundle (cie polyglot --viewspec all) — C4, state machines, workflows, impact views; null when the pass found nothing nameable
  source: DataSource;
  label: string;
  loading: boolean;
  loadError: string;
  chat: ChatMessage[];
  chatBusy: boolean;
  jobId: string | null; // active "Connect a repo" job, survives dialog close
  repoScan: RepoScan | null; // language inventory from connect-a-repo flows

  // mastery journey — per-project state, localStorage-backed (lib/mastery.ts).
  // Null until the owning components load it after mount (browser-only API).
  mastery: MasteryState | null;
  pendingTrace: { entryId: number; title: string } | null; // a card handed a trace to the chat

  // workspace state
  view: StageView; // what the middle stage shows
  canvasChart: ChatChartSpec | null; // the chart sent to the canvas (view === "chart")
  canvasPolyglot: string | null; // the named-diagram bundle key on the canvas (view === "chart") — mutually exclusive with canvasChart
  canvasConcept: CanvasConcept | null; // a usecase's flowchart/sequence on the canvas (view === "chart") — mutually exclusive with the other two
  mapSelected: VizElement | null; // map bubble picked; the chat offers it as a referent
  llm: LlmConfig; // who answers — hydrated from localStorage after mount
  llmSettingsOpen: boolean; // the connection settings dialog (topbar owns it)
  chatOpen: boolean; // Ask CIE docked on the right — collapsible so a chart-heavy view can take the full width; remembered like the model settings are
  pendingAsk: string | null; // click-to-chat: a question any chart/card handed to the chat

  // atlas dashboard — the Selection Context (lib/atlas.ts). One click
  // updates this; all four views re-render from it.
  atlasSelection: AtlasSelection;
  atlasView: "containers" | "components" | "sequence" | "dataflow";
  atlasFactsOnly: boolean; // "Facts only" — dim/filter inferred elements everywhere

  // XFILTER — the cross-chart filter (lib/chart-filter.ts). A click on any
  // canned chart's bucket lands here; every sibling chart, the Fixes and
  // Promises lists and the map re-render from it. ONE filter at a time:
  // second click on the same bucket releases, a different bucket replaces
  // (the atlasSelection precedent) — chart-filter.nextChartFilter owns the
  // rule, the emitters just call setChartFilter.
  chartFilter: ChartFilter | null;
  setChartFilter: (f: ChartFilter | null) => void;
  clearChartFilter: () => void;

  // source panel — click a chart element with a location, see the code
  sourceViewer: SourceViewerRequest | null;
  storageRoot: string | null;
  sourceRoot: string | null; // absolute root of a consented local-folder project (URL clones are deleted after analysis — null there, honestly)
  sourceCache: Record<string, string>; // fetched file contents, by repo-relative path

  demoKind: "banking" | "spring" | "polyglot"; // which bundled sample is loaded
  loadDemo: (kind?: "banking" | "spring" | "polyglot") => Promise<void>;
  loadSpringDemo: () => Promise<void>; // the second bundled sample — the Spring/Java+Kotlin stand-in
  loadPolyglotDemo: () => Promise<void>; // the polyglot five-service sample — the default one
  setCustom: (
    report: CieReport | null,
    viewspec: CieViewSpec | null,
    concepts: ConceptTree | null,
    label: string,
    extra?: {
      repoScan?: RepoScan | null;
      deps?: CieDeps | null;
      runtime?: CieRuntime | null;
      stories?: CieStories | null;
      quality?: CieQuality | null;
      cochange?: CieCochange | null;
      overlap?: CieOverlap | null;
      drift?: CieDrift | null;
      stack?: TechStack | null;
      polyglotSpecs?: PolyglotBundle | null;
      storageRoot?: string | null;
      sourceRoot?: string | null;
    }
  ) => void;
  reset: () => void;
  pushChat: (m: ChatMessage) => void;
  setChatBusy: (b: boolean) => void;
  clearChat: () => void;
  setJobId: (id: string | null) => void;
  setView: (v: StageView) => void;
  openChartOnCanvas: (spec: ChatChartSpec) => void;
  openPolyglotOnCanvas: (artifact: string) => void; // a named diagram the chat asked for
  openConceptOnCanvas: (conceptId: number, kind: "flowchart" | "sequence") => void; // a usecase's diagram the chat (or section) asked for
  closeCanvasChart: () => void;
  setMapSelected: (el: VizElement | null) => void;
  setPendingAsk: (q: string | null) => void;
  setLlm: (cfg: LlmConfig) => void;
  hydrateLlm: () => void;
  setLlmSettingsOpen: (open: boolean) => void;
  setChatOpen: (open: boolean) => void;
  hydrateChatOpen: () => void;
  selectFunction: (symbolId: number) => void;
  openSourceViewer: (req: SourceViewerRequest) => void;
  closeSourceViewer: () => void;
  cacheSource: (path: string, content: string) => void;

  // atlas dashboard
  setAtlasSelection: (ref: AtlasRef | null) => void; // click anywhere in any view
  drillUp: () => void; // breadcrumb: reset to the level above
  resetAtlas: () => void; // empty space / System crumb
  setAtlasView: (v: "containers" | "components" | "sequence" | "dataflow") => void;
  setAtlasFactsOnly: (b: boolean) => void;

  // RFC-0024 stage 2 — the persona state (ux-spec §14.2). Switch =
  // re-plan, not re-page: scope carries when meaningful (containers
  // survive all switches; module/symbol reset to the persona's default),
  // the facts-only USER override beats the preset default for the
  // session, each preset remembers its own last state in sessionStorage,
  // and every switch is footer-disclosed.
  persona: PersonaId;
  personaFactsOnlyTouched: boolean; // the user manually toggled this session
  personaDisclosure: string | null; // §14.2-5 — the last switch, footer-printed
  setPersona: (id: PersonaId) => void;
  markFactsOnlyTouched: () => void;

  // RFC-0024 stage 4 — the R5a context chips (ux-spec §3-CHIP/§2.3): every
  // element-resolving click auto-adds its chip (dedupe by id, cap 24 — the
  // 25th click evicts the oldest and says so; RFC-0023 adds the same-
  // revision rule — stale selections are not code space). Chips SURVIVE
  // persona switches and scope releases (G3). R4 follows chips only (G5).
  chatContext: ChatContextElement[];
  chipNotice: string | null; // eviction / repeat-pulse disclosure (G4)
  addChip: (el: ChatContextElement) => void;
  removeChip: (id: string) => void;
  clearChips: () => void;

  // mastery journey
  loadMastery: () => void; // (re)load for the CURRENT project; call after mount / project change
  updateMastery: (fn: (m: MasteryState) => MasteryState) => void; // pure edit + persist
  resetMastery: () => void; // start over — but never silently: callers confirm first
  setPendingTrace: (t: { entryId: number; title: string } | null) => void;
}

export const useCie = create<CieState>((set, get) => ({
  report: null,
  viewspec: null,
  concepts: null,
  deps: null,
  runtime: null,
  stories: null,
  quality: null,
  cochange: null,
  overlap: null,
  drift: null,
  stack: null,
  polyglotSpecs: null,
  demoKind: "polyglot",
  source: null,
  label: "",
  loading: true,
  loadError: "",
  chat: [],
  chatBusy: false,
  jobId: null,
  repoScan: null,
  mastery: null,
  pendingTrace: null,
  view: "start",
  canvasChart: null,
  canvasPolyglot: null,
  canvasConcept: null,
  mapSelected: null,
  llm: DEFAULT_LLM,
  llmSettingsOpen: false,
  chatOpen: true,
  pendingAsk: null,
  sourceViewer: null,
  storageRoot: null,
  sourceRoot: null,
  sourceCache: {},
  atlasSelection: ATLAS_RESET,
  atlasView: "containers",
  atlasFactsOnly: false,
  chartFilter: null,
  persona: "fresher" as PersonaId, // §14.2-6: first-run default = Fresher
  personaFactsOnlyTouched: false,
  personaDisclosure: null,
  chatContext: [],
  chipNotice: null,

  loadDemo: async (kind) => {
    const demoKind = kind ?? get().demoKind ?? "polyglot";
    const dir = demoKind === "spring" ? "/data/spring" : demoKind === "polyglot" ? "/data/polyglot" : "/data";
    set({ loading: true, loadError: "" });
    try {
      // deps.json + runtime.json + stories.json are optional extras: a project
      // without them still loads, and those views show honest empty states.
      // cochange.json is deliberately not bundled: the sample lives inside
      // this engine's own monorepo without its own .git root, so `cie
      // cochange` there would mine the ENGINE's commit history, not the
      // sample's — honestly null beats a misleading real-looking chart.
      const [report, viewspec, concepts, deps, runtime, stories, quality, overlap, drift, stack, polyglotSpecs] = await Promise.all([
        fetch(`${dir}/report.json`).then((r) => r.json()),
        fetch(`${dir}/viewspec.json`).then((r) => r.json()),
        fetch(`${dir}/concepts.json`).then((r) => r.json()),
        fetch(`${dir}/deps.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/runtime.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/stories.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/quality.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/overlap.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/drift.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/stack.json`).then((r) => r.json()).catch(() => null),
        // PRD v2.0 named diagrams (C4, state machines, workflows, impact).
        // Optional like every extra: a sample without the file loads, the
        // Named-diagrams view shows the honest empty state.
        fetch(`${dir}/polyglot.json`).then((r) => (r.ok ? r.json() : null)).catch(() => null),
      ]);
      const fault=await fetch(`${dir}/fault.json`).then(r=>r.ok?r.json():null).catch(()=>null);
      if(report && fault?.revision===report.rev && fault.execution_performed===false && fault.runtime_observed===false) report.fault_analysis=fault;
      set({
        report,
        viewspec,
        concepts,
        deps,
        runtime,
        stories,
        quality,
        cochange: null,
        overlap,
        drift,
        stack,
        polyglotSpecs,
        demoKind,
        source: "demo",
        label:
          demoKind === "spring"
            ? `Sample project: a Spring Boot service (${report.files.length} indexed files — Java + Kotlin)`
            : demoKind === "polyglot"
              ? `Sample project: a five-service harbor system (${report.files.length} indexed files — Java, Kotlin, Rust, TypeScript and Python)`
              : `Sample project: a small banking app (${report.files.length} indexed files — Python, SQL and shell)`,
        loading: false,
        chat: [],
        chatBusy: false,
        repoScan: null,
        view: "start",
        canvasChart: null,
        canvasPolyglot: null,
        canvasConcept: null,
        mapSelected: null,
  chatContext: [],
        // The sample project has no local-folder root on this machine.
        // Switching away from a connected project must drop its source
        // state too, or the panel would try to resolve demo files against
        // the stale root — surfacing wrong-project code or a confusing
        // read error (issue #6). Mirrors setCustom()'s reset.
        storageRoot: null,
        sourceRoot: null,
        sourceCache: {},
        sourceViewer: null,
        pendingAsk: null,
        atlasSelection: ATLAS_RESET,
        atlasView: "containers",
        atlasFactsOnly: false,
        chartFilter: null,
      });
      // This workspace is now the "last opened" one — the dashboard reopens
      // it on the next launch (workspace-memory, a nicety that never gates
      // a fact).
      rememberWorkspace({ kind: "sample", demo: demoKind });
    } catch {
      set({ loading: false, loadError: "Could not load the sample data. Please refresh the page." });
    }
  },

  setCustom: (report, viewspec, concepts, label, extra) =>
    set({
      report,
      viewspec,
      concepts,
      deps: extra?.deps ?? null,
      runtime: extra?.runtime ?? null,
      stories: extra?.stories ?? null,
      quality: extra?.quality ?? null,
      cochange: extra?.cochange ?? null,
      overlap: extra?.overlap ?? null,
      drift: extra?.drift ?? null,
      stack: extra?.stack ?? null,
      polyglotSpecs: extra?.polyglotSpecs ?? null,
      source: "custom",
      label,
      loading: false,
      loadError: "",
      chat: [],
      chatBusy: false,
      // The scan only exists for connect-a-repo flows; switching to the
      // sample or to uploaded files honestly drops it.
      repoScan: extra?.repoScan ?? null,
      // Only local-folder projects keep a readable root on this machine.
      // URL clones are deleted after analysis and uploads never touched
      // disk — the source panel says so honestly for those.
      sourceRoot: extra?.sourceRoot ?? null,
      storageRoot: extra?.storageRoot ?? extra?.sourceRoot ?? null,
      sourceCache: {},
      sourceViewer: null,
      // A new project starts on its own front page, not on an old chart.
      view: get().view === "chart" ? "start" : get().view,
      canvasChart: null,
      canvasPolyglot: null,
      canvasConcept: null,
      mapSelected: null,
  chatContext: [],
      atlasSelection: ATLAS_RESET,
      atlasView: "containers",
      atlasFactsOnly: false,
      chartFilter: null,
    }),

  reset: () => {
    void useCie.getState().loadDemo(useCie.getState().demoKind);
  },

  loadSpringDemo: async () => {
    await useCie.getState().loadDemo("spring");
  },

  loadPolyglotDemo: async () => {
    await useCie.getState().loadDemo("polyglot");
  },

  pushChat: (m) => set((s) => ({ chat: [...s.chat, m] })),
  setChatBusy: (b) => set({ chatBusy: b }),
  clearChat: () => set({ chat: [] }),
  setJobId: (id) => set({ jobId: id }),

  setView: (v) => set({ view: v }),

  // The three canvas senders are mutually exclusive: opening one closes
  // the others, so the stage never has to arbitrate between a chat chart,
  // a named diagram, and a usecase diagram occupying the same view slot.
  openChartOnCanvas: (spec) => set({ canvasChart: spec, canvasPolyglot: null, canvasConcept: null, view: "chart" }),
  openPolyglotOnCanvas: (artifact) => set({ canvasPolyglot: artifact, canvasChart: null, canvasConcept: null, view: "chart" }),
  openConceptOnCanvas: (conceptId, kind) => set({ canvasConcept: { conceptId, kind }, canvasChart: null, canvasPolyglot: null, view: "chart" }),
  closeCanvasChart: () => set({ canvasChart: null, canvasPolyglot: null, canvasConcept: null, view: "start" }),

  setMapSelected: (el) =>
    set((s) => ({
      mapSelected: el,
      ...(el
        ? addChipState(s.chatContext, {
            id: el.id,
            label: el.label,
            kind: el.elementKind,
            revision: s.report?.rev ?? 0,
            files: el.evidence?.file ? [el.evidence.file] : [],
            loc: el.evidence?.file ? { file: el.evidence.file, byteStart: el.evidence.start, byteEnd: el.evidence.end } : undefined,
          })
        : {}),
    })),

  setPendingAsk: (q) => set({ pendingAsk: q }),

  setLlm: (cfg) => {
    saveLlmConfig(cfg);
    set({ llm: cfg });
  },

  // Called once after mount (localStorage is browser-only).
  hydrateLlm: () => set({ llm: loadLlmConfig() }),

  setLlmSettingsOpen: (open) => set({ llmSettingsOpen: open }),

  setChatOpen: (open) => {
    try { window.localStorage.setItem(CHAT_OPEN_KEY, open ? "1" : "0"); } catch {}
    set({ chatOpen: open });
  },
  // Called once after mount (localStorage is browser-only) — defaults to
  // open, same as the server-rendered page, so there's nothing to flicker.
  hydrateChatOpen: () => {
    try {
      if (window.localStorage.getItem(CHAT_OPEN_KEY) === "0") set({ chatOpen: false });
    } catch {}
  },

  selectFunction: (symbolId) => set(s => {
    const symbol=s.report?.symbols.find(x=>Number(x.id)===symbolId);
    if(!symbol||!s.report||!['Function','Method','Test'].includes(symbol.kind))return {};
    const file=s.report.files[symbol.loc.file];
    const loc={file,byteStart:symbol.loc.start,byteEnd:symbol.loc.end};
    const ref={kind:'symbol' as const,id:symbol.qual_name,label:symbol.name,loc};
    return {view:'atlas' as const,atlasSelection:{primary:ref,scope:'symbol' as const},sourceViewer:{...loc,elName:symbol.name},...addChipState(s.chatContext,{id:`function:${symbolId}`,label:symbol.name,kind:'symbol',revision:s.report.rev??0,loc,files:[file],sourceTitle:'Function selection'})};
  }),
  openSourceViewer: (req) => set({ sourceViewer: req }),
  closeSourceViewer: () => set({ sourceViewer: null }),
  cacheSource: (path, content) => set((s) => ({ sourceCache: { ...s.sourceCache, [path]: content } })),

  // atlas — a click anywhere lands here; the scope follows the ref kind.
  // Clicking the already-selected thing again zooms back out one level
  // (toggle), so drill-down never becomes a trap.
  setAtlasSelection: (ref) =>
    set((s) => {
      if (!ref) return { atlasSelection: ATLAS_RESET };
      if (s.atlasSelection.primary?.kind === ref.kind && s.atlasSelection.primary?.id === ref.id) {
        return { atlasSelection: ATLAS_RESET }; // second click = release
      }
      const files = ref.kind === "container"
        ? (s.report?.files ?? []).filter(f => containerOfPath(f, s.stack?.apps) === ref.id)
        : ref.loc?.file ? [ref.loc.file] : ref.kind === "module" ? [ref.id] : [];
      const chip = addChipState(s.chatContext, { id: ref.id, label: ref.label, kind: ref.kind, revision: s.report?.rev ?? 0, loc: ref.loc, files, sourceTitle: "Atlas" });
      return { atlasSelection: { primary: ref, scope: scopeForRef(ref) }, ...chip };
    }),
  drillUp: () =>
    set((s) => {
      const p = s.atlasSelection.primary;
      if (!p) return {};
      if (p.kind === "symbol") {
        const file = p.loc?.file;
        return file
          ? { atlasSelection: { primary: { kind: "module", id: file, label: file.split("/").pop() ?? file, loc: { file } }, scope: "module" } }
          : { atlasSelection: ATLAS_RESET };
      }
      if (p.kind === "module" || p.kind === "store") {
        const i = p.id.indexOf("/");
        return i > 0
          ? { atlasSelection: { primary: { kind: "container", id: p.id.slice(0, i), label: p.id.slice(0, i) }, scope: "container" } }
          : { atlasSelection: ATLAS_RESET };
      }
      if (p.kind === "concept") {
        const file = p.loc?.file;
        const i = file ? file.indexOf("/") : -1;
        const container = i > 0 ? file!.slice(0, i) : file ? "(project root)" : null;
        return container
          ? { atlasSelection: { primary: { kind: "container", id: container, label: container }, scope: "container" } }
          : { atlasSelection: ATLAS_RESET };
      }
      return { atlasSelection: ATLAS_RESET };
    }),
  resetAtlas: () => set({ atlasSelection: ATLAS_RESET }),
  setAtlasView: (v) => set({ atlasView: v }),

  // XFILTER — a chart bucket click (toggle/replace rule lives in
  // chart-filter.nextChartFilter) and the banner's clear affordance.
  setChartFilter: (f) => set((s) => ({ chartFilter: nextChartFilter(s.chartFilter, f) })),
  clearChartFilter: () => set({ chartFilter: null }),
  setAtlasFactsOnly: (b) => set({ atlasFactsOnly: b, personaFactsOnlyTouched: true }),
  markFactsOnlyTouched: () => set({ personaFactsOnlyTouched: true }),
  setPersona: (id) =>
    set((s) => {
      if (id === s.persona) return {};
      const prev = PERSONA_PRESETS[s.persona];
      const next = PERSONA_PRESETS[id];
      // §14.2-4: each preset remembers its own last state (sessionStorage).
      savePersonaMemory(prev.id, {
        factsOnlyOverride: s.personaFactsOnlyTouched ? s.atlasFactsOnly : null,
        factsOnlyValue: s.atlasFactsOnly,
      });
      const mem = loadPersonaMemory(id);
      // §14.2-3: the user's manual override wins for the session; otherwise
      // the new preset's default (or its remembered override) applies.
      const factsOnly =
        s.personaFactsOnlyTouched
          ? s.atlasFactsOnly
          : (mem?.factsOnlyOverride ?? next.defaultFactsOnly);
      // §14.2-2: container scope survives all persona switches; module /
      // symbol scope RESETS to the persona's default (never stay inside a
      // function you were handed in another view). Chips (stage 4) and the
      // change context SURVIVE every switch (G3 extended).
      const scopeCarries =
        s.atlasSelection.primary === null || s.atlasSelection.primary?.kind === "container";
      const disclosure = `Atlas re-planned for: ${next.label} — facts-only ${
        factsOnly ? "on" : "off"
      }${scopeCarries ? "" : ", symbol scope reset"}${mem ? " (last state restored)" : ""}.`;
      return {
        persona: id,
        atlasFactsOnly: factsOnly,
        personaDisclosure: disclosure,
        ...(scopeCarries ? {} : { atlasSelection: ATLAS_RESET }),
      };
    }),
  // One add path (chat-context.addChipState): dedupe → pulse notice, cap 24
  // → evict-oldest notice, same-revision → stale chips drop (RFC-0023).
  addChip: (el) => set((s) => addChipState(s.chatContext, el)),
  removeChip: (id) =>
    set((s) => ({ chatContext: s.chatContext.filter((c) => c.id !== id), mapSelected: s.mapSelected?.id === id ? null : s.mapSelected, chipNotice: null })),
  clearChips: () => set({ chatContext: [], mapSelected: null, chipNotice: null }),

  // mastery: keyed by the loaded project (label); load reads localStorage.
  // Switching projects drops the old state from memory so every component
  // that renders it re-reads the right person's journey.
  loadMastery: () => {
    const key = masteryKeyOf(get().source, get().label);
    set((s) => (s.mastery?.key === key ? s : { mastery: loadMasteryState(key) }));
  },
  updateMastery: (fn) => {
    const m = get().mastery;
    if (!m) return; // loaded after mount only
    const next = fn(m);
    if (next === m) return;
    set({ mastery: next });
    saveMasteryState(next);
  },
  resetMastery: () => {
    const key = masteryKeyOf(get().source, get().label);
    const fresh = freshMastery(key);
    set({ mastery: fresh });
    saveMasteryState(fresh);
  },
  setPendingTrace: (t) => set({ pendingTrace: t }),
}));
